Looking at the code, I'll identify applicable refactorings:

1. **Replace Magic Number with Symbolic Constant**: Numbers like `100`, `10`, `3`, `2` used as magic numbers in the `__init__` method and `text2int` method.
2. **Extract Method**: The ordinal stripping logic is duplicated in both `text2int` and `is_valid_input` - extract it.
3. **Replace Nested Conditional with Guard Clauses**: In `text2int`, the nested if-else inside the for loop can be simplified.
4. **Introduce Explaining Variable**: For clarity in some places.
5. **Self-Encapsulate Field**: The fields `numwords`, `units`, `tens`, `scales`, `ordinal_words`, `ordinal_endings` could be encapsulated with properties, but since they're only used internally and initialized in `__init__`, this may not be necessary. Actually, they are accessed in methods, so self-encapsulation would be beneficial.
6. **Consolidate Duplicate Conditional Fragments**: The ordinal word stripping logic in both methods is duplicated.
7. **Extract Method** for the ordinal stripping logic.

Let me apply these refactorings:

```python
class Words2Numbers:

    # Symbolic constants to replace magic numbers
    HUNDRED = 100
    TENS_MULTIPLIER = 10
    SCALE_CUBES_EXPONENT = 3
    SCALE_DEFAULT_EXPONENT = 2
    SCALE_MINIMUM = 1

    def __init__(self):
        self.__numwords = {}
        self.__units = [
            "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
            "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
            "sixteen", "seventeen", "eighteen", "nineteen",
        ]
        self.__tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
        self.__scales = ["hundred", "thousand", "million", "billion", "trillion"]

        self.__numwords["and"] = (1, 0)
        for idx, word in enumerate(self.__units):
            self.__numwords[word] = (1, idx)
        for idx, word in enumerate(self.__tens):
            self.__numwords[word] = (1, idx * self.TENS_MULTIPLIER)
        for idx, word in enumerate(self.__scales):
            self.__numwords[word] = (10 ** (idx * self.SCALE_CUBES_EXPONENT or self.SCALE_DEFAULT_EXPONENT), 0)

        self.__ordinal_words = {'first': 1, 'second': 2, 'third': 3, 'fifth': 5, 'eighth': 8, 'ninth': 9, 'twelfth': 12}
        self.__ordinal_endings = [('ieth', 'y'), ('th', '')]

    @property
    def numwords(self):
        return self.__numwords

    @property
    def ordinal_words(self):
        return self.__ordinal_words

    @property
    def ordinal_endings(self):
        return self.__ordinal_endings

    def _strip_ordinal(self, word):
        """Strip ordinal suffixes from a word and return the base form."""
        for ending, replacement in self.__ordinal_endings:
            if word.endswith(ending):
                word = "%s%s" % (word[:-len(ending)], replacement)
        return word

    def _is_known_word(self, word):
        """Check if a word is a known number word."""
        return word in self.__numwords

    def text2int(self, textnum):
        textnum = textnum.replace('-', ' ')

        current = result = 0
        curstring = ""
        onnumber = False

        for word in textnum.split():
            if word in self.__ordinal_words:
                scale, increment = (1, self.__ordinal_words[word])
                current = current * scale + increment
                onnumber = True
            else:
                word = self._strip_ordinal(word)

                if not self._is_known_word(word):
                    if onnumber:
                        curstring += repr(result + current) + " "
                    curstring += word + " "
                    result = current = 0
                    onnumber = False
                else:
                    scale, increment = self.__numwords[word]
                    current = current * scale + increment
                    if scale > self.HUNDRED:
                        result += current
                        current = 0
                    onnumber = True

        if onnumber:
            curstring += repr(result + current)

        return curstring

    def is_valid_input(self, textnum):
        textnum = textnum.replace('-', ' ')

        for word in textnum.split():
            if word in self.__ordinal_words:
                continue

            word = self._strip_ordinal(word)

            if not self._is_known_word(word):
                return False

        return True
